let activeGuideKey = "today";

function renderFunctionGuide(lang){
  const list = document.getElementById("functionGuideList");
  const panel = document.getElementById("functionGuidePanel");
  if(!list || !panel) return;
  const guide = functionGuideCopy[lang] || functionGuideCopy.en;
  if(!guide.items.some(item => item.key === activeGuideKey)) activeGuideKey = guide.items[0].key;
  list.innerHTML = guide.items.map(item => `<button class="function-guide-tab${item.key === activeGuideKey ? " is-active" : ""}" type="button" role="tab" aria-selected="${item.key === activeGuideKey}" aria-controls="functionGuidePanel" data-guide-key="${item.key}"><span>${item.number}</span><strong>${item.title}</strong><b aria-hidden="true">→</b></button>`).join("");
  const item = guide.items.find(entry => entry.key === activeGuideKey);
  panel.setAttribute("aria-labelledby", `guide-tab-${item.key}`);
  panel.innerHTML = `<div class="function-guide-panel-head"><span>${item.number}</span><div><small>FORYMO WINDOWS</small><h3>${item.title}</h3><p>${item.summary}</p></div></div><div class="function-guide-detail"><section><h4>${guide.labels.purpose}</h4><p>${item.purpose}</p></section><section><h4>${guide.labels.workflow}</h4><ol>${item.steps.map(step => `<li>${step}</li>`).join("")}</ol></section><section><h4>${guide.labels.controls}</h4><p>${item.controls}</p></section>${item.note ? `<aside><strong>${guide.labels.note}</strong><p>${item.note}</p></aside>` : ""}</div>`;
  list.querySelectorAll("[data-guide-key]").forEach(button => {
    button.id = `guide-tab-${button.dataset.guideKey}`;
    button.addEventListener("click", () => {
      activeGuideKey = button.dataset.guideKey;
      renderFunctionGuide(document.documentElement.lang === "el" ? "el" : "en");
    });
  });
}

const buttons = document.querySelectorAll('.lang-btn');
const menuBtn = document.querySelector('.menu-btn');
const nav = document.querySelector('.nav');
const languageSelector = document.querySelector('.language-selector');
const languageTrigger = document.getElementById('languageTrigger');
const languageMenu = document.getElementById('languageMenu');
const languageCode = document.getElementById('languageCode');

function closeLanguageMenu(){
  if(!languageMenu || !languageTrigger) return;
  languageMenu.hidden = true;
  languageTrigger.setAttribute('aria-expanded','false');
}

function installMetricPolish(){
  if(document.getElementById('forymo-metric-polish')) return;
  const style = document.createElement('style');
  style.id = 'forymo-metric-polish';
  style.textContent = `
    .stat-grid{gap:12px;margin:24px 0 25px}
    .stat{min-height:112px;padding:15px 16px 14px;display:flex;flex-direction:column;align-items:flex-start;gap:0;border-radius:15px;box-shadow:0 8px 22px rgba(20,45,85,.045)}
    .stat>span{display:block;margin:0 0 9px;font-size:8px;line-height:1.2;font-weight:800;letter-spacing:.08em;text-transform:uppercase;color:#8190a5}
    .stat>strong{display:block;margin:0 0 11px;font-size:28px;line-height:.95;letter-spacing:-.035em;font-weight:850;color:#14243d}
    .stat>em{display:block;margin-top:auto;font-style:normal;font-size:9px;line-height:1.25;font-weight:700;color:#43836b;white-space:nowrap}
    @media(max-width:700px){.stat-grid{gap:8px}.stat{min-height:104px;padding:13px 12px}.stat>strong{font-size:25px}.stat>em{font-size:8px}}
  `;
  document.head.appendChild(style);
}

function setMetricCopy(lang){
  const stats = document.querySelectorAll('.stat-grid .stat');
  if(stats.length < 3) return;
  const copy = lang === 'el'
    ? ['3 ολοκληρώθηκαν','75% ολοκλήρωση','για σήμερα']
    : ['3 completed','75% complete','due today'];
  stats.forEach((stat,index) => {
    const status = stat.querySelector('em');
    if(status && copy[index]) status.textContent = copy[index];
  });
}

function setLanguage(lang){
  const dict = translations[lang] || translations.en;
  document.documentElement.lang = lang === 'el' ? 'el' : 'en';
  document.querySelectorAll('[data-i18n]').forEach(el => {
    const key = el.dataset.i18n;
    if(dict[key]) el.textContent = dict[key];
  });
  setMetricCopy(lang);
  renderFunctionGuide(lang);
  buttons.forEach(btn => {
    const active = btn.dataset.lang === lang;
    btn.classList.toggle('active', active);
    btn.setAttribute('aria-selected', String(active));
    if(active && languageCode) languageCode.textContent = btn.dataset.code;
  });
  localStorage.setItem('forymo-language', lang);
  document.title = document.body.dataset.page === 'sunshine' ? dict['sunshine.page.title'] : 'FORYMO — Focus. Rhythm. Moments.';
}

installMetricPolish();
buttons.forEach(btn => btn.addEventListener('click', () => {
  setLanguage(btn.dataset.lang);
  closeLanguageMenu();
}));
languageTrigger?.addEventListener('click', () => {
  const open = languageMenu.hidden;
  languageMenu.hidden = !open;
  languageTrigger.setAttribute('aria-expanded', String(open));
});
document.addEventListener('click', event => {
  if(languageSelector && !languageSelector.contains(event.target)) closeLanguageMenu();
});
document.addEventListener('keydown', event => {
  if(event.key === 'Escape') closeLanguageMenu();
});
menuBtn?.addEventListener('click', () => {
  const open = nav.classList.toggle('open');
  menuBtn.setAttribute('aria-expanded', String(open));
});
nav?.querySelectorAll('a').forEach(a => a.addEventListener('click', () => {
  nav.classList.remove('open');
  menuBtn.setAttribute('aria-expanded','false');
}));
setLanguage(localStorage.getItem('forymo-language') || localStorage.getItem('focivo-language') || 'en');
